-- Second wave of equipment-maker prospects for Rainbow DJ Lab / Full Spectrum. Outreach only.
-- Checked on their own pages 2026-10-20: Sennheiser lists sponsoring@sennheiser.com (categories music, education, diversity; no rules posted).
-- The On-Stage donation cited was Feb 2017 (Harmony Project, via NAMM) and gives no way to request one.
-- Hercules DJ Academy is free tutorials only; no donation or school program on the page.
-- All other rows come from a research note and are unverified.
insert into fs_grant_deadlines (funder, program, kind, deadline_date, opens_date, amount, verified, url, notes, verified_on, level, project, priority, status, eligibility, next_step)
select * from (values
('Hercules','DJ Academy / beginner controllers','relationship',null::date,null::date,'12 beginner controllers + headphones',false,'https://www.hercules.com/en-us/dj-academy-2/','Free tutorial library confirmed. No donation, school or nonprofit program on the page. Good classroom fit; ask through their support or partnership contact.','2026-10-20'::date,'corporate','djclass',1,'to_research','No published application.','Send an inquiry: 12 matching beginner controllers and headphones.'),
('Sennheiser','Brand partnerships / sponsoring (music, education, diversity)','relationship',null::date,null::date,'12 wired DJ headphones, teaching mics',false,'https://www.sennheiser.com/en-de/about-us/our-responsibility/partnerships/partnerships--sponsorings-categories','Contact: sponsoring@sennheiser.com. Page lists categories but no rules or region limits. Sponsorship inquiry, not a charity application.','2026-10-20'::date,'corporate','djclass',1,'to_research','Unknown; email to ask.','Email sponsoring@sennheiser.com with the headphone request.'),
('Audio-Technica','Headphone donations','relationship',null::date,null::date,'12 closed-back wired headphones, mics',false,'https://www.museumofmakingmusic.org/more/news/a-sound-investment-audio-technica-donates-headphones','Donation precedent reported by the Museum of Making Music; no public US application verified.','2026-10-20'::date,'corporate','djclass',1,'to_research','No published application.','Find their US contact and send the headphone request.'),
('HARMAN / JBL','HARMAN Inspired (youth, music, technology)','relationship',null::date,null::date,'PA system, mics, headphones',false,'https://www.harman.com/inspired','Corporate giving fit for youth music education. Unsolicited route unverified.','2026-10-20'::date,'corporate','wednesdays',2,'to_research','Unknown.','Ask HARMAN Inspired how to submit a request.'),
('Focusrite / Novation / ADAM Audio','Education partnerships','relationship',null::date,null::date,'interfaces, beat-making controllers, monitors, masterclass',false,'https://focusrite.com/solutions/education','Education offering and masterclasses exist; free-equipment eligibility not established.','2026-10-20'::date,'corporate','djclass',2,'to_research','Unknown.','Ask about an institutional partnership.'),
('On-Stage','Product donations to music education','relationship',null::date,null::date,'12 controller/laptop stands, mic and speaker stands',false,'https://on-stage.com/news/article/442','Only evidence is a Feb 2017 donation to Harmony Project; no request process. Confirm they still donate.','2026-10-20'::date,'corporate','djclass',2,'to_research','Unknown.','Contact On-Stage and ask whether they consider requests.'),
('Odyssey','Cases and DJ booths','relationship',null::date,null::date,'DJ booths, controller cases, transport cases',false,'https://www.odysseygear.com/','Covers the booth and case need. No donation program verified.','2026-10-20'::date,'corporate','djclass',2,'to_research','Unknown.','Contact Odyssey with the booth and case list.'),
('Gator','Cases and stands','relationship',null::date,null::date,'cases, stands, transport protection',false,'https://shop.gatorco.com/contact/','Contact form only; no donation program verified.','2026-10-20'::date,'corporate','djclass',2,'to_research','Unknown.','Use their contact form.'),
('Koss','Education headphones','relationship',null::date,null::date,'12 wired headphones, spare pads',false,'https://koss.com/pages/education-contact','Milwaukee company. The contact is for education sales, not a donation program. Ask for a discount or donation.','2026-10-20'::date,'corporate','djclass',3,'to_research','Unknown.','Use the education contact to ask about donated or discounted sets.'),
('QSC','People & Communities giving','relationship',null::date,null::date,'sound reinforcement for showcases',false,'https://www.qsc.com/sustainability/people-communities','Publishes a charitable giving commitment; application route unverified.','2026-10-20'::date,'corporate','wednesdays',3,'to_research','Unknown.','Find the recipient team.'),
('Reloop','Controllers, turntables, headphones','relationship',null::date,null::date,'controllers, demo turntable setup, headphones',false,'https://www.reloop.com/imprint','Published contact info@reloop.com. Ask for a US education or marketing representative.','2026-10-20'::date,'corporate','djclass',3,'to_research','Unknown.','Email info@reloop.com.'),
('CHAUVET DJ','Showcase lighting','relationship',null::date,null::date,'student-operated lighting package',false,'https://www.chauvetdj.com/contact-us/','Contact route only; no nonprofit program verified.','2026-10-20'::date,'corporate','wednesdays',3,'to_research','Unknown.','Use their contact form.'),
('Yamaha','Community support / music education','relationship',null::date,null::date,'mixer, speakers, keyboards',false,'https://www.yamaha.com/en/sustainability/social/community-support/','Documents community support; eligibility for an unsolicited request unconfirmed.','2026-10-20'::date,'corporate','wednesdays',3,'to_research','Unknown.','Ask Yamaha USA about community support requests.')
) as v(funder,program,kind,deadline_date,opens_date,amount,verified,url,notes,verified_on,level,project,priority,status,eligibility,next_step)
where not exists (select 1 from fs_grant_deadlines g where g.funder = v.funder and g.program = v.program);
